     item_id
    ,shop_id
    ,cspu_id
    ,model_id
    ,local_hour
from srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
where grass_region in (${grass_region})  and local_date = ${local_date}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cspu_label_${grass_region_without_quote} AS
select
     cspu_id
    ,order_cnt as cspu_l1d_order_cnt
from srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d
WHERE grass_region IN (${grass_region}) and local_date = date_sub(${local_date}, 1)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cheapest_model_list_${grass_region_without_quote} AS
select
     local_hour as cheapest_hour
    ,c.cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,business_type
from (
    SELECT
         cspu_id
        ,model_id
        ,item_id
        ,shop_id
        ,local_hour
        ,business_type
    FROM srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
    WHERE grass_region = ${grass_region} AND local_date = ${local_date}
) c
left join cspu_label_${grass_region_without_quote} d on c.cspu_id=d.cspu_id
where d.cspu_l1d_order_cnt>0 or d.cspu_l1d_order_cnt is null
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cheapest_cspu_all_model_${grass_region_without_quote} AS
SELECT
    a.*
FROM all_cspu_model_${grass_region_without_quote} a
inner join (
    select
         cheapest_hour
        ,cspu_id
    from cheapest_model_list_${grass_region_without_quote}
    group by cheapest_hour,cspu_id
) b on a.cspu_id=b.cspu_id and a.local_hour=b.cheapest_hour
;
--sql_divide_splitter--

